    title: "\u0633\u0646\u062F \u062C\u0644\u0633\u0647\u200C\u06CC \u0635\u0641\u0631 \u0632\u0631\u0648\u0627\u0646\u06CC\u0627",
    body: "## \u0627\u0646\u062A\u0638\u0627\u0631\u0627\u062A \u0648 \u067E\u06CC\u0645\u0627\u0646 \u0628\u0627\u0632\u06CC\n- **\u062D\u0627\u0644 \u0648 \u0647\u0648\u0627\u06CC \u0628\u0627\u0632\u06CC:** \u0627\u0633\u0637\u0648\u0631\u0647\u200C\u0627\u06CC\u060C \u067E\u0631 \u0627\u0632 \u0631\u0645\u0632 \u0648 \u0631\u0627\u0632 \u0632\u0645\u0627\u0646\u060C \u0686\u0627\u0644\u0634\u200C\u0647\u0627\u06CC \u0627\u062E\u0644\u0627\u0642\u06CC \u0648 \u0628\u0642\u0627 \u062F\u0631 \u0628\u06CC\u0627\u0628\u0627\u0646 \u0648 \u0628\u06CC\u0634\u0647\u200C\u0647\u0627.\n- **\u0632\u0645\u0627\u0646\u200C\u0628\u0646\u062F\u06CC:** \u062C\u0644\u0633\u0627\u062A \u0647\u0641\u062A\u06AF\u06CC \u067E\u0646\u062C\u200C\u0634\u0646\u0628\u0647\u200C\u0647\u0627 \u0639\u0635\u0631 \u0633\u0627\u0639\u062A \u06F1\u06F8:\u06F0\u06F0.\n- **\u062E\u0637\u0648\u0637 \u0642\u0631\u0645\u0632 (Lines & Veils):** \u0622\u0632\u0627\u0631 \u0628\u06CC\u200C\u062F\u0644\u06CC\u0644 \u06A9\u0648\u062F\u06A9\u0627\u0646 \u0648 \u062D\u06CC\u0648\u0627\u0646\u0627\u062A \u0628\u06CC\u200C\u067E\u0646\u0627\u0647\u060C \u062E\u0634\u0648\u0646\u062A \u0628\u06CC\u0634 \u0627\u0632 \u062D\u062F \u062A\u0648\u0635\u06CC\u0641\u06CC.\n- **\u06A9\u0627\u0631\u062A X:** \u062F\u0631 \u0647\u0631 \u0644\u062D\u0638\u0647 \u0647\u0631 \u0628\u0627\u0632\u06CC\u06A9\u0646\u06CC \u0627\u062D\u0633\u0627\u0633 \u0646\u0627\u0631\u0627\u062D\u062A\u06CC \u06A9\u0631\u062F \u0645\u06CC\u200C\u062A\u0648\u0627\u0646\u062F \u0628\u062F\u0648\u0646 \u0646\u06CC\u0627\u0632 \u0628\u0647 \u062A\u0648\u0636\u06CC\u062D\u060C \u062A\u0648\u0642\u0641 \u0628\u0627\u0632\u06CC \u0631\u0627 \u062F\u0631\u062E\u0648\u0627\u0633\u062A \u06A9\u0646\u062F.",
    visibility: "party",
